#include <stdio.h>

static int prec(char c) {
    if (c == '*' || c == '/') return 2;
    if (c == '+' || c == '-') return 1;
    return 0;
}

int main(void) {
    const char *in = "a+b*c-d";
    char st[64], out[64];
    int top = 0, k = 0;
    for (int i = 0; in[i]; i++) {
        char c = in[i];
        if (c >= 'a' && c <= 'z') { out[k++] = c; }
        else {
            while (top > 0 && prec(st[top - 1]) >= prec(c)) out[k++] = st[--top];
            st[top++] = c;
        }
    }
    while (top > 0) out[k++] = st[--top];
    out[k] = 0;
    printf("中缀: %s\n", in);
    printf("后缀: %s\n", out);
    return 0;
}
